arguments.new_str:
using Aspire.Hosting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluations;

[TestClass]
public sealed class ChatEvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;
    private static DistributedApplication? s_app;

    [AssemblyInitialize]
    public static async Task Initialize(TestContext context)
    {
        var storageDir = Path.Combine(
            AppContext.BaseDirectory, "..", "..", "..", "eval-results");

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: await GetChatConfigurationAsync());
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }

        if (s_app is not null)
        {
            await s_app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Response_Is_Coherent_And_Relevant()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(Chat_Response_Is_Coherent_And_Relevant));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var result = await scenario.EvaluateAsync(messages);
        scenario.RecordResult(result);

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(metric.Value.Diagnostics?.HasFailures ?? false,
                $"Metric '{metric.Key}' reported failures.");
        }
    }

    [TestMethod]
    public async Task Chat_Response_Handles_Follow_Up()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(Chat_Response_Handles_Follow_Up));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about renewable energy sources."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "Which one is most cost-effective?"));
        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var result = await scenario.EvaluateAsync(messages);
        scenario.RecordResult(result);

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(metric.Value.Diagnostics?.HasFailures ?? false,
                $"Metric '{metric.Key}' reported failures.");
        }
    }

    private static async Task<ChatConfiguration> GetChatConfigurationAsync()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        s_app = await appHost.BuildAsync();
        await s_app.StartAsync();

        var chatClient = s_app.Services.GetRequiredService<IChatClient>();
        return new ChatConfiguration(chatClient);
    }
}

